SELECT define_provision($q$LSC_PLANNING_SCHEME_2018@2025-05-02$q$, $q$def open carport$q$, 'DEFINITION', $q$Means a carport with: (a) two sides or more open, and a side is also considered open where the roof covering adjacent to that side is not less than 500 millimetres from another building or a side or rear lot boundary; and (b) not less than one-third of its perimeter open.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$SC1.2 Table SC1.2.2 (p.SC1-35)$q$, NULL, $q$https://www.livingstone.qld.gov.au/files/sharedassets/public/v/1/doing-business/documents/10_Sch1_Definitions_V4_Adopted_2025_02_18.pdf$q$, NULL, NULL);
SELECT define_provision($q$LSC_PLANNING_SCHEME_2018@2025-05-02$q$, $q$def outermost projection$q$, 'DEFINITION', $q$Outermost projection, of a building or structure, means the outermost part of the building or structure, other than a part that is: (a) a retractable blind; or (b) a fixed screen; or (c) a rainwater fitting; or (d) an ornamental attachment.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$SC1.2 Table SC1.2.2 (pp.SC1-35 to SC1-36)$q$, NULL, $q$https://www.livingstone.qld.gov.au/files/sharedassets/public/v/1/doing-business/documents/10_Sch1_Definitions_V4_Adopted_2025_02_18.pdf$q$, NULL, NULL);
