SELECT define_provision($q$LSC_PLANNING_SCHEME_2018@2025-05-02$q$, $q$def mean height$q$, 'DEFINITION', $q$Mean height, of a building or structure, means the vertical height worked out by dividing the total elevational area of the wall of a building or structure facing the boundary by the horizontal length of the building or structure facing the boundary.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$SC1.2 Table SC1.2.2 (p.SC1-35)$q$, NULL, $q$https://www.livingstone.qld.gov.au/files/sharedassets/public/v/1/doing-business/documents/10_Sch1_Definitions_V4_Adopted_2025_02_18.pdf$q$, NULL, NULL);
