INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$LSC.lsc_ldr_lmdr_twp_front_corner_class10a@2025-05-02$q$, $q$QDC11.A1a.FRONTAGE_SETBACK$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
SELECT define_provision($q$LSC_PLANNING_SCHEME_2018@2025-05-02$q$, $q$Low density residential zone code Table 6.7.1.4.1 AO3.2; Low-medium density residential zone code Table 6.7.2.4.1 AO2.2; Township zone code Table 6.5.8.4.1 AO2.2; Schedule 10 Table SC10.1.2 Road Front$q$, 'ACCEPTABLE_OUTCOME', $q$AO3.2 Buildings or structures have a setback from side, rear, and road frontage lot boundaries in compliance with the setback standards identified in Table SC10.1.2 of Schedule 10. || AO2.2 Buildings or structures have a setback from side, rear, and road frontage lot boundaries in compliance with the setback standards identified in Table SC10.1.2 of Schedule 10. || AO2.2 Buildings or structures have a setback from side, rear, and road frontage lot boundaries in compliance with the setback standards identified in Table SC10.1.2 of Schedule 10. || Table SC10.1.2: Setback standards for development located in the Low Density Residential Zone, the Low-Medium Density Residential Zone, or the Township Zone | All lot sizes | Circumstance (C): If a shade sail or an ‘open carport’, the shade sail or ‘open car port’ may have a road frontage setback that is less than the setback specified in Circumstance (A) or Circumstance (B) only if: (a) no more than one (1) shade sail or open carport per lot is non-compliant with the setbacks specified in Circumstance (A) or Circumstance (B); (b) the shade sail or open carport is not located within a nine (9) by nine (9) metre truncation at the corner of two road frontages (refer to Figure SC10.1.5); (c) the height of the shade sail or open carport does not exceed 3.5 metres above ground level to the apex; (d) the maximum width is the lesser of seven (7) metres or fifty (50) per centum of the width of the road frontage from which vehicle access is obtained (measured from the inside of the outermost supporting posts); (e) supporting posts have a setback of at least one (1) metre from any road frontage lot boundary; (f) there are zero enclosing or screening elements (for example, doors, walls, windows, screens or similar) along any line of supports of that part of the shade sail or open carport which does not comply with the setback specified in Circumstance (A) or Circumstance (B); and (g) the sum perimeter dimension of supports located within the setback does not exceed fifteen (15) per centum of the total perimeter dimension (along the line of supports) of that part of the shade sail or carport within the same setback (refer to Figure SC10.1.7).$q$, 'VERIFIED_VERBATIM', $q$Low density residential zone code p.P6-146 (PDF p.5); Low-medium density residential zone code p.P6-154 (PDF p.4); Township zone code p.P6-124 to P6-125 (PDF pp.4-5); Schedule 10 p.SC10-9 to SC10-12 (PDF pp.9-12)$q$, NULL, $q$Low density residential zone code / Low-medium density residential zone code / Township zone code + Schedule 10$q$, NULL, $q$https://www.livingstone.qld.gov.au/files/sharedassets/public/v/1/doing-business/documents/10_Sch10_Boundary_setbacks_for_zones_V4_Adopted_2025_02_18.pdf$q$, $q$SC1.2 Setback: "the shortest distance, measured horizontally, between the outermost projection of the building or structure to the vertical projection of the boundary of the lot where the building or structure is." Outermost projection excludes a retractable blind, fixed screen, rainwater fitting or ornamental attachment. Outermost projection height is measured to ground level directly below that point.$q$, $q$lsc_ldr_lmdr_twp_front_open_carport$q$);
SELECT define_rule($q${"rule_id": "LSC.lsc_ldr_lmdr_twp_front_open_carport", "instrument_version": "LSC_PLANNING_SCHEME_2018@2025-05-02", "topic": "SETBACK.FRONTAGE", "title": "Low density residential zone code Table 6.7.1.4.1 AO3.2; Low-medium density residential zone code Table 6.7.2.4.1 AO2.2; Township zone code Table 6.5.8.4.1 AO2.2; Schedule 10 Table SC10.1.2 Road Front", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": {"op": "unencoded", "text": "AO3.2 Buildings or structures have a setback from side, rear, and road frontage lot boundaries in compliance with the setback standards identified in Table SC10.1.2 of Schedule 10. || AO2.2 Buildings or structures have a setback from side, rear, and road frontage lot boundaries in compliance with the setback standards identified in Table SC10.1.2 of Schedule 10. || AO2.2 Buildings or structures have a setback from side, rear, and road frontage lot boundaries in compliance with the setback standards identified in Table SC10.1.2 of Schedule 10. || Table SC10.1.2: Setback standards for development located in the Low Density Residential Zone, the Low-Medium Density Residential Zone, or the Township Zone | All lot sizes | Circumstance (C): If a shade sail or an ‘open carport’, the shade sail or ‘open car port’ may have a road frontage setback that is less than the setback specified in Circumstance (A) or Circumstance (B) only if: (a) no more than one (1) shade sail or open carport per lot is non-compliant with the setbacks specified in Circumstance (A) or Circumstance (B); (b) the shade sail or open carport is not located within a nine (9) by nine (9) metre truncation at the corner of two road frontages (refer to Figure SC10.1.5); (c) the height of the shade sail or open carport does not exceed 3.5 metres above ground level to the apex; (d) the maximum width is the lesser of seven (7) metres or fifty (50) per centum of the width of the road frontage from which vehicle access is obtained (measured from the inside of the outermost supporting posts); (e) supporting posts have a setback of at least one (1) metre from any road frontage lot boundary; (f) there are zero enclosing or screening elements (for example, doors, walls, windows, screens or similar) along any line of supports of that part of the shade sail or open carport which does not comply with the setback specified in Circumstance (A) or Circumstance (B); and (g) the sum perimeter dimension of supports located within the setback does not exceed fifteen (15) per centum of the total perimeter dimension (along the line of supports) of that part of the shade sail or carport within the same setback (refer to Figure SC10.1.7).", "extracted_value": 1, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2025-05-02", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "LIVINGSTONE"}, {"level": "ZONE", "zone": "LSC:LOW_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "LSC:LOW_MEDIUM_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "LSC:TOWNSHIP"}], "subjects": ["CLASS_10A"], "sources": [{"key": "lsc_ldr_lmdr_twp_front_open_carport", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"unit\": \"m\", \"conditions\": [\"no more than one non-compliant shade sail or open carport per lot\", \"not within 9 m x 9 m corner truncation\", \"height <= 3.5 m to apex\", \"width <= lesser of 7 m or 50% of the road frontage width from which vehicle access is obtained\", \"supporting posts setback >= 1 m from any road frontage lot boundary\", \"no enclosing or screening elements along any line of supports within the setback\", \"supports within setback <= 15% of perimeter (Figure SC10.1.7)\"], \"exceptions\": [], \"formula_text\": null, \"parameter\": \"road frontage setback of supporting posts of a shade sail or open carport that does not meet Circumstance (A)/(B)\", \"operator\": \"conditional\", \"value\": 1}\nStructure scope 'shade sail or 'open carport'' mapped by keyword to ['CLASS_10A']\nAlternative provision to QDC/QHC: YES - Part 1 s1.6(3): \"This planning scheme, through Part 5, regulates building work in accordance with sections 32 and 33 of the Building Act 1975.\" and s1.6(4)(c) lists \"Relevant zone codes\" (and (e) \"Seaspray Local Plan\") as building assessment provisions; the s1.6 editor's note cites \"alternative boundary clearances and site cover provisions for Class 1 and 10 structures under section 33\". Table 5.6.1 makes standalone Class 10a building work accepted subject to requirements against these AOs.\nResearcher notes: 'Open carport' defined in SC1.2 (two or more sides open, not less than one-third of perimeter open)."}$q$::jsonb);
