SELECT define_rule($q${"rule_id": "LSC.lsc_ldr_lmdr_twp_side_rear_frontage_gt15", "instrument_version": "LSC_PLANNING_SCHEME_2018@2025-05-02", "topic": "SETBACK.SIDE", "title": "Low density residential zone code Table 6.7.1.4.1 AO3.2; Low-medium density residential zone code Table 6.7.2.4.1 AO2.2; Township zone code Table 6.5.8.4.1 AO2.2; Schedule 10 Table SC10.1.2 Side and R", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "TABLE", "measurement": "SCHEME_SETBACK_SIDE", "operator": ">=", "value": 1.5, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2025-05-02", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "LIVINGSTONE"}, {"level": "ZONE", "zone": "LSC:LOW_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "LSC:LOW_MEDIUM_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "LSC:TOWNSHIP"}], "subjects": ["ANY"], "sources": [{"key": "lsc_ldr_lmdr_twp_side_rear_frontage_gt15", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"unit\": \"m\", \"conditions\": [\"applies to side AND rear boundaries\", \"OPH 2 m to 4.5 m: 1.5 m\", \"OPH 4.501 m to 7.5 m: 2 m\", \"OPH > 7.5 m: 2 m plus 0.5 m for every 3 m or part of 3 m by which height exceeds 7.5 m\"], \"exceptions\": [\"Class 10a building or part may be within the setback - see Circumstance (C) rule\", \"rainwater tank (incl. stand) <= 2.4 m high (Circumstance (D)(a))\", \"ornamental/horticultural pergola or structure <= 2.4 m, unenclosed (Circumstance (D)(b))\", \"building or structure (or combination such as fence + retaining wall) not exceeding 2 m outermost projection height / combined height (Circumstance (F))\"], \"formula_text\": \"OPH > 7.5 m: 2 + 0.5 * ceil((OPH - 7.5)/3)\", \"parameter\": \"side and rear boundary setback by outermost projection height (OPH)\", \"operator\": \">=\", \"value\": 1.5}\nLot conditions (not encoded): 