INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$LSC.lsc_ldr_lmdr_twp_side_rear_frontage_gt15@2025-05-02$q$, $q$QDC11.A2a.SIDE_REAR_CLEARANCE$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
SELECT define_provision($q$LSC_PLANNING_SCHEME_2018@2025-05-02$q$, $q$Low density residential zone code Table 6.7.1.4.1 AO3.2; Low-medium density residential zone code Table 6.7.2.4.1 AO2.2; Township zone code Table 6.5.8.4.1 AO2.2; Schedule 10 Table SC10.1.2 Side and R$q$, 'ACCEPTABLE_OUTCOME', $q$AO3.2 Buildings or structures have a setback from side, rear, and road frontage lot boundaries in compliance with the setback standards identified in Table SC10.1.2 of Schedule 10. || AO2.2 Buildings or structures have a setback from side, rear, and road frontage lot boundaries in compliance with the setback standards identified in Table SC10.1.2 of Schedule 10. || AO2.2 Buildings or structures have a setback from side, rear, and road frontage lot boundaries in compliance with the setback standards identified in Table SC10.1.2 of Schedule 10. || Table SC10.1.2: Setback standards for development located in the Low Density Residential Zone, the Low-Medium Density Residential Zone, or the Township Zone | All lot sizes | The side and rear setbacks identified in Circumstance (A) or Circumstance (B) apply to buildings or structures unless the building or structure complies with Circumstance (C), or Circumstance (D), or Circumstance (E), or Circumstance (F). | Circumstance (C): If a Class 10a building or part as defined under the Building Code of Australia, the building or part may be within the side and rear setbacks identified in Table SC10.1.9 or Table SC10.1.10 only if: (a) the ‘outermost projection height’ is not more than 4.5 metres, and the building or structure has a ‘mean height’ of not more than 3.5 metres; and (b) the total length of all buildings or parts, of any class, within the setback is not more than nine (9) metres along any one boundary; and (c) the Class 10a buildings or parts within the setback are located no closer than 1.5 metre to a required window in a habitable room of an adjoining dwelling. | Circumstance (D): If the following: (a) it is a rainwater tank (including any supporting structure such as a stand) not more than 2.4 metres in height above ground level; or (b) it is a pergola or other structure which: (i) is not more than 2.4 metres in height above ground level at the boundary; and (ii) is not enclosed by walls or roof; and (iii) is primarily ornamental or for horticulture purposes; and (iv) is not used for recreational purposes, entertainment purposes or the like. | Circumstance (F): A building or structure that: (a) if standalone, does not have an ‘outermost projection height’ exceeding two (2) metres; or (b) if involving a combination with other buildings or structures, does not result in a combined height exceeding two (2) metres. Editor’s note: An example of a ‘combination’ is a fence and a retaining wall or a building and a retaining wall.$q$, 'VERIFIED_VERBATIM', $q$Low density residential zone code p.P6-146 (PDF p.5); Low-medium density residential zone code p.P6-154 (PDF p.4); Township zone code p.P6-124 to P6-125 (PDF pp.4-5); Schedule 10 p.SC10-9 to SC10-10 (PDF pp.9-10); Tables SC10.1.9/SC10.1.10 at SC10-21 (PDF p.21)$q$, NULL, $q$Low density residential zone code / Low-medium density residential zone code / Township zone code + Schedule 10$q$, NULL, $q$https://www.livingstone.qld.gov.au/files/sharedassets/public/v/1/doing-business/documents/10_Sch10_Boundary_setbacks_for_zones_V4_Adopted_2025_02_18.pdf$q$, $q$SC1.2 Setback: "the shortest distance, measured horizontally, between the outermost projection of the building or structure to the vertical projection of the boundary of the lot where the building or structure is." Outermost projection excludes a retractable blind, fixed screen, rainwater fitting or ornamental attachment. Outermost projection height is measured to ground level directly below that point.$q$, $q$lsc_ldr_lmdr_twp_side_rear_class10a_concession$q$);
SELECT define_rule($q${"rule_id": "LSC.lsc_ldr_lmdr_twp_side_rear_class10a_concession", "instrument_version": "LSC_PLANNING_SCHEME_2018@2025-05-02", "topic": "SETBACK.SIDE", "title": "Low density residential zone code Table 6.7.1.4.1 AO3.2; Low-medium density residential zone code Table 6.7.2.4.1 AO2.2; Township zone code Table 6.5.8.4.1 AO2.2; Schedule 10 Table SC10.1.2 Side and R", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_SETBACK_SIDE", "operator": ">=", "value": {"op": "unencoded", "text": "AO3.2 Buildings or structures have a setback from side, rear, and road frontage lot boundaries in compliance with the setback standards identified in Table SC10.1.2 of Schedule 10. || AO2.2 Buildings or structures have a setback from side, rear, and road frontage lot boundaries in compliance with the setback standards identified in Table SC10.1.2 of Schedule 10. || AO2.2 Buildings or structures have a setback from side, rear, and road frontage lot boundaries in compliance with the setback standards identified in Table SC10.1.2 of Schedule 10. || Table SC10.1.2: Setback standards for development located in the Low Density Residential Zone, the Low-Medium Density Residential Zone, or the Township Zone | All lot sizes | The side and rear setbacks identified in Circumstance (A) or Circumstance (B) apply to buildings or structures unless the building or structure complies with Circumstance (C), or Circumstance (D), or Circumstance (E), or Circumstance (F). | Circumstance (C): If a Class 10a building or part as defined under the Building Code of Australia, the building or part may be within the side and rear setbacks identified in Table SC10.1.9 or Table SC10.1.10 only if: (a) the ‘outermost projection height’ is not more than 4.5 metres, and the building or structure has a ‘mean height’ of not more than 3.5 metres; and (b) the total length of all buildings or parts, of any class, within the setback is not more than nine (9) metres along any one boundary; and (c) the Class 10a buildings or parts within the setback are located no closer than 1.5 metre to a required window in a habitable room of an adjoining dwelling. | Circumstance (D): If the following: (a) it is a rainwater tank (including any supporting structure such as a stand) not more than 2.4 metres in height above ground level; or (b) it is a pergola or other structure which: (i) is not more than 2.4 metres in height above ground level at the boundary; and (ii) is not enclosed by walls or roof; and (iii) is primarily ornamental or for horticulture purposes; and (iv) is not used for recreational purposes, entertainment purposes or the like. | Circumstance (F): A building or structure that: (a) if standalone, does not have an ‘outermost projection height’ exceeding two (2) metres; or (b) if involving a combination with other buildings or structures, does not result in a combined height exceeding two (2) metres. Editor’s note: An example of a ‘combination’ is a fence and a retaining wall or a building and a retaining wall.", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2025-05-02", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "LIVINGSTONE"}, {"level": "ZONE", "zone": "LSC:LOW_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "LSC:LOW_MEDIUM_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "LSC:TOWNSHIP"}], "subjects": ["CLASS_10A", "CLASS_1", "OUTDOOR_STRUCTURE"], "sources": [{"key": "lsc_ldr_lmdr_twp_side_rear_class10a_concession", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"unit\": \"m\", \"conditions\": [\"applies to side AND rear boundaries\", \"outermost projection height <= 4.5 m and 'mean height' <= 3.5 m\", \"total length of all buildings or parts (any class) within the setback <= 9 m along any one boundary\", \"Class 10a buildings or parts within the setback no closer than 1.5 m to a required window in a habitable room of an adjoining dwelling\"], \"exceptions\": [\"rainwater tank (incl. supporting stand) <= 2.4 m above ground level: no setback\", \"pergola/other structure <= 2.4 m at boundary, unenclosed, ornamental or horticultural, not recreational: no setback\", \"building or structure (or combination e.g. fence + retaining wall) <= 2 m outermost projection height / combined height: no setback\"], \"formula_text\": null, \"parameter\": \"Class 10a building within side/rear setback of Table SC10.1.9 / SC10.1.10\", \"operator\": \"conditional\", \"value\": null}\nStructure scope 'a Class 10a building or part as defined under the Building Code of Australia; rainwater tank; pergola or other structure; building or structure not exceeding 2 m' mapped by keyword to ['CLASS_10A', 'CLASS_1', 'OUTDOOR_STRUCTURE']\nAlternative provision to QDC/QHC: YES - Part 1 s1.6(3): \"This planning scheme, through Part 5, regulates building work in accordance with sections 32 and 33 of the Building Act 1975.\" and s1.6(4)(c) lists \"Relevant zone codes\" (and (e) \"Seaspray Local Plan\") as building assessment provisions; the s1.6 editor's note cites \"alternative boundary clearances and site cover provisions for Class 1 and 10 structures under section 33\". Table 5.6.1 makes standalone Class 10a building work accepted subject to requirements against these AOs.\nResearcher notes: No minimum distance is stated for a conforming Class 10a building within the setback (i.e. may be built to the boundary subject to conditions); value left null. Mirrors QDC MP1.2 A2(d)-style concession with council-specific limits."}$q$::jsonb);
