INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$LSC.lsc_ldr_lmdr_twp_side_rear_class10a_concession@2025-05-02$q$, $q$QDC11.A2a.SIDE_REAR_CLEARANCE$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
SELECT define_provision($q$LSC_PLANNING_SCHEME_2018@2025-05-02$q$, $q$Medium density residential zone code Table 6.7.3.4.1 AO2.2; Major tourism zone code Table 6.8.1.4.1 AO2.1 (Capricorn International Resort Precinct); Major tourism zone code Table 6.8.1.4.1 AO4.2 (Grea$q$, 'ACCEPTABLE_OUTCOME', $q$AO2.2 Buildings or structures have a setback from side, rear, and road frontage lot boundaries in compliance with the setback standards identified in Table SC10.1.3 of Schedule 10. || AO2.1 Buildings or structures have a setback from side, rear, and road frontage lot boundaries in compliance with the setback standards identified in Table SC10.1.3 of Schedule 10. || AO4.2 Buildings or structures have a setback from side, rear, and road frontage lot boundaries in compliance with the setback standards identified in Table SC10.1.3 of Schedule 10. || Table SC10.1.3: Setback standards for development located in the Medium Density Residential Zone, the Major Tourism Zone (Capricorn International Resort Precinct), or the Major Tourism Zone (Great Keppel Island Precinct) | Development having an ‘outermost projection height’ equal to or below ten (10) metres located on any lot size. | The road frontage lot boundary setbacks identified in Circumstance (A) or Circumstance (B) apply to buildings or structures unless the building or structure complies with Circumstance (C), or Circumstance (D), or Circumstance (E). | Circumstance (A): If the lot is not a corner lot, buildings or structures have a setback from road frontage lot boundaries in accordance with the following: (a) a dwelling has a setback of at least three (3) metres; (b) decks, patios, pergolas, verandahs, balconies, gazebos or the like have a setback of at least three (3) metres; (c) a garage has a setback of at least six (6) metres; (d) a standalone Class 10a building under the Building Code of Australia being a shed, garage or carport has a setback of at least six (6) metres; and (e) any other building or structure has a setback of at least six (6) metres. | Circumstance (D): If it is a roofed gatehouse or arch which: (a) has a maximum area of four (4) square metres; and (b) is not more than (2) metres wide to the street; and (c) is not more than three (3) metres in height. | Circumstance (E): A building or structure that: (a) if standalone, does not have an ‘outermost projection height’ exceeding two (2) metres; or (b) if involving a combination with other buildings or structures, does not result in a combined height exceeding two (2) metres. Editor’s note: An example of a ‘combination’ is a fence and a retaining wall or a building and a retaining wall.$q$, 'VERIFIED_VERBATIM', $q$Medium density residential zone code p.P6-165 (PDF p.7); Major tourism zone code p.P6-174 (PDF p.4); Major tourism zone code p.P6-176 (PDF p.6); Schedule 10 p.SC10-13 to SC10-16 (PDF pp.13-16)$q$, NULL, $q$Medium density residential zone code / Major tourism zone code / Major tourism zone code + Schedule 10$q$, NULL, $q$https://www.livingstone.qld.gov.au/files/sharedassets/public/v/1/doing-business/documents/10_Sch10_Boundary_setbacks_for_zones_V4_Adopted_2025_02_18.pdf$q$, $q$SC1.2 Setback: "the shortest distance, measured horizontally, between the outermost projection of the building or structure to the vertical projection of the boundary of the lot where the building or structure is." Outermost projection excludes a retractable blind, fixed screen, rainwater fitting or ornamental attachment. Outermost projection height is measured to ground level directly below that point.$q$, $q$lsc_mdr_mt_front_class10a$q$);
SELECT define_rule($q${"rule_id": "LSC.lsc_mdr_mt_front_class10a", "instrument_version": "LSC_PLANNING_SCHEME_2018@2025-05-02", "topic": "SETBACK.FRONTAGE", "title": "Medium density residential zone code Table 6.7.3.4.1 AO2.2; Major tourism zone code Table 6.8.1.4.1 AO2.1 (Capricorn International Resort Precinct); Major tourism zone code Table 6.8.1.4.1 AO4.2 (Grea", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": 6, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2025-05-02", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "LIVINGSTONE"}, {"level": "ZONE", "zone": "LSC:MEDIUM_DENSITY_RESIDENTIAL"}, {"level": "PRECINCT", "precinct": "LSC:MAJOR_TOURISM/CAPRICORN_INTERNATIONAL_RESORT"}, {"level": "PRECINCT", "precinct": "LSC:MAJOR_TOURISM/GREAT_KEPPEL_ISLAND"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "lsc_mdr_mt_front_class10a", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"unit\": \"m\", \"conditions\": [\"lot is not a corner lot\", \"garage forming part of a dwelling: 6 m (not Class 10a standalone but same value)\", \"decks, patios, pergolas, verandahs, balconies, gazebos or the like: 3 m\"], \"exceptions\": [\"open carport / shade sail: see Circumstance (C) rule (posts >= 1 m)\", \"roofed gatehouse or arch <= 4 m2, <= 2 m wide to street, <= 3 m high\", \"building or structure (incl. fence + retaining wall combination) with outermost projection height / combined height not exceeding 2 m\"], \"formula_text\": null, \"parameter\": \"road frontage setback, standalone Class 10a building (shed, garage, carport) and any other building or structure\", \"operator\": \">=\", \"value\": 6}\nStructure scope 'a standalone Class 10a building under the Building Code of Australia being a shed, garage or carport; any other building or structure' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: YES - Part 1 s1.6(3): \"This planning scheme, through Part 5, regulates building work in accordance with sections 32 and 33 of the Building Act 1975.\" and s1.6(4)(c) lists \"Relevant zone codes\" (and (e) \"Seaspray Local Plan\") as building assessment provisions; the s1.6 editor's note cites \"alternative boundary clearances and site cover provisions for Class 1 and 10 structures under section 33\". Table 5.6.1 makes standalone Class 10a building work accepted subject to requirements against these AOs.\nResearcher notes: Zone code AO adopts Schedule 10 by reference. Swimming pools, if a 'structure', fall under (e) 'any other building or structure' (6 m) unless under 2 m outermost projection height (in-ground pools likely exempt via Circumstance (E)); scheme does not name pools expressly. Table SC10.1.3 has a second row for development with an outermost projection height exceeding 10 m (front: 6 m plus 0.3 m per metre over 10 m; side/rear: 3 m plus 0.3 m per metre over 10 m); not recorded as a separate rule because Class 10 structures of that height are not expected."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$LSC.lsc_mdr_mt_front_class10a@2025-05-02$q$;
INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$LSC.lsc_mdr_mt_front_class10a@2025-05-02$q$, $q$QDC12.A1a.ROAD_SETBACK$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$LSC.lsc_mdr_mt_front_class10a@2025-05-02$q$, $q$QDC11.A1a.FRONTAGE_SETBACK$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
SELECT define_provision($q$LSC_PLANNING_SCHEME_2018@2025-05-02$q$, $q$Medium density residential zone code Table 6.7.3.4.1 AO2.2; Major tourism zone code Table 6.8.1.4.1 AO2.1 (Capricorn International Resort Precinct); Major tourism zone code Table 6.8.1.4.1 AO4.2 (Grea$q$, 'ACCEPTABLE_OUTCOME', $q$AO2.2 Buildings or structures have a setback from side, rear, and road frontage lot boundaries in compliance with the setback standards identified in Table SC10.1.3 of Schedule 10. || AO2.1 Buildings or structures have a setback from side, rear, and road frontage lot boundaries in compliance with the setback standards identified in Table SC10.1.3 of Schedule 10. || AO4.2 Buildings or structures have a setback from side, rear, and road frontage lot boundaries in compliance with the setback standards identified in Table SC10.1.3 of Schedule 10. || Table SC10.1.3: Setback standards for development located in the Medium Density Residential Zone, the Major Tourism Zone (Capricorn International Resort Precinct), or the Major Tourism Zone (Great Keppel Island Precinct) | Development having an ‘outermost projection height’ equal to or below ten (10) metres located on any lot size. | The road frontage lot boundary setbacks identified in Circumstance (A) or Circumstance (B) apply to buildings or structures unless the building or structure complies with Circumstance (C), or Circumstance (D), or Circumstance (E). | Circumstance (B): If the lot is a corner lot, buildings or structures have a setback from road frontage lot boundaries in accordance with the following: (a) if the ‘depth of a lot’ has an average of greater than twenty-four (24) metres: (i) a dwelling has a setback of at least three (3) metres; (ii) decks, patios, pergolas, verandahs, balconies, gazebos or the like have a setback of at least three (3) metres; (iii) a garage has a setback of at least six (6) metres; (iv) a standalone Class 10a buildings under the Building Code of Australia being a shed, garage or carport has a setback of at least six (6) metres; (v) any other building or structure has a setback of at least six (6) metres; and (vi) despite (a)(i), (a)(ii), (a)(iii), (a)(iv) or (a)(v), no building or structure over two (2) metres high is built on the lot within a nine (9) by nine (9) metre truncation at the corner of two road frontages (refer to Figure SC10.1.5); or (b) if the ‘depth of a lot’ has an average of twenty-four (24) metres or less: (i) for the ‘primary road frontage’: (A) a dwelling has a setback of at least three (3) metres; (B) decks, patios, pergolas, verandahs, gazebos or the like have a setback of at least three (3) metres; (C) a garage has a setback of at least six (6) metres; (D) a standalone Class 10a buildings under the Building Code of Australia being a shed, garage or carport has a setback of at least six (6) metres; (E) any other building or structure has a setback of at least six (6) metres; and (F) despite (b)(i)(A), (b)(i)(B), (b)(i)(C), (b)(i)(D), or (b)(i)(E), no building or structure over two (2) metres high is built on the lot within a nine (9) by nine (9) metre truncation at the corner of two road frontages (refer to Figure SC10.1.5);$q$, 'VERIFIED_VERBATIM', $q$Medium density residential zone code p.P6-165 (PDF p.7); Major tourism zone code p.P6-174 (PDF p.4); Major tourism zone code p.P6-176 (PDF p.6); Schedule 10 p.SC10-13 to SC10-16 (PDF pp.13-16)$q$, NULL, $q$Medium density residential zone code / Major tourism zone code / Major tourism zone code + Schedule 10$q$, NULL, $q$https://www.livingstone.qld.gov.au/files/sharedassets/public/v/1/doing-business/documents/10_Sch10_Boundary_setbacks_for_zones_V4_Adopted_2025_02_18.pdf$q$, $q$SC1.2 Setback: "the shortest distance, measured horizontally, between the outermost projection of the building or structure to the vertical projection of the boundary of the lot where the building or structure is." Outermost projection excludes a retractable blind, fixed screen, rainwater fitting or ornamental attachment. Outermost projection height is measured to ground level directly below that point.$q$, $q$lsc_mdr_mt_front_corner_class10a$q$);
SELECT define_rule($q${"rule_id": "LSC.lsc_mdr_mt_front_corner_class10a", "instrument_version": "LSC_PLANNING_SCHEME_2018@2025-05-02", "topic": "SETBACK.FRONTAGE", "title": "Medium density residential zone code Table 6.7.3.4.1 AO2.2; Major tourism zone code Table 6.8.1.4.1 AO2.1 (Capricorn International Resort Precinct); Major tourism zone code Table 6.8.1.4.1 AO4.2 (Grea", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": 6, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2025-05-02", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "LIVINGSTONE"}, {"level": "ZONE", "zone": "LSC:MEDIUM_DENSITY_RESIDENTIAL"}, {"level": "PRECINCT", "precinct": "LSC:MAJOR_TOURISM/CAPRICORN_INTERNATIONAL_RESORT"}, {"level": "PRECINCT", "precinct": "LSC:MAJOR_TOURISM/GREAT_KEPPEL_ISLAND"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "lsc_mdr_mt_front_corner_class10a", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"unit\": \"m\", \"conditions\": [\"lot is a corner lot\", \"depth of lot average > 24 m: 6 m from road frontage lot boundaries\", \"depth of lot average <= 24 m: 6 m from the 'primary road frontage' (secondary frontage per Figure SC10.1.6 - out of scope)\", \"no building or structure over 2 m high within a 9 m x 9 m truncation at the corner of two road frontages\"], \"exceptions\": [\"Circumstances (C) open carport/shade sail, (D) gatehouse/arch, (E) <= 2 m structures as for non-corner lots\"], \"formula_text\": null, \"parameter\": \"road frontage setback on corner lot (primary road frontage), standalone Class 10a building and any other building or structure\", \"operator\": \">=\", \"value\": 6}\nLot conditions (not encoded): corner lots\nStructure scope 'a standalone Class 10a buildings under the Building Code of Australia being a shed, garage or carport; any other building or structure' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: YES - Part 1 s1.6(3): \"This planning scheme, through Part 5, regulates building work in accordance with sections 32 and 33 of the Building Act 1975.\" and s1.6(4)(c) lists \"Relevant zone codes\" (and (e) \"Seaspray Local Plan\") as building assessment provisions; the s1.6 editor's note cites \"alternative boundary clearances and site cover provisions for Class 1 and 10 structures under section 33\". Table 5.6.1 makes standalone Class 10a building work accepted subject to requirements against these AOs.\nResearcher notes: Secondary road frontage limb (b)(ii) omitted (out of scope; refers to Figure SC10.1.6 image)."}$q$::jsonb);
