SELECT define_provision($q$LSC_PLANNING_SCHEME_2018@2025-05-02$q$, $q$Medium density residential zone code Table 6.7.3.4.1 AO2.2; Major tourism zone code Table 6.8.1.4.1 AO2.1 (Capricorn International Resort Precinct); Major tourism zone code Table 6.8.1.4.1 AO4.2 (Grea$q$, 'TABLE', $q$AO2.2 Buildings or structures have a setback from side, rear, and road frontage lot boundaries in compliance with the setback standards identified in Table SC10.1.3 of Schedule 10. || AO2.1 Buildings or structures have a setback from side, rear, and road frontage lot boundaries in compliance with the setback standards identified in Table SC10.1.3 of Schedule 10. || AO4.2 Buildings or structures have a setback from side, rear, and road frontage lot boundaries in compliance with the setback standards identified in Table SC10.1.3 of Schedule 10. || Table SC10.1.3: Setback standards for development located in the Medium Density Residential Zone, the Major Tourism Zone (Capricorn International Resort Precinct), or the Major Tourism Zone (Great Keppel Island Precinct) | Development having an ‘outermost projection height’ equal to or below ten (10) metres located on any lot size. | The side and rear setbacks identified in Circumstance (A) or Circumstance (B) apply to buildings or structures unless the building or structure complies with Circumstance (C), or Circumstance (D), or Circumstance (E), or Circumstance (F). | Circumstance (A): If the lot is rectangular or near rectangular with a road frontage of fifteen (15) metres or less, the setback for a part of the building or structure is in accordance with Table SC10.1.9. || Table SC10.1.9: Side and rear lot boundary setbacks where lot road frontages are fifteen metres or less | Road Frontage (in metres) | Side and Rear Boundary Setback (in metres) | At any point where the ‘outermost projection height’ is between 2 metres and 4.5 metres | At any point where the ‘outermost projection height’ is 4.501 metres to 7.5 metres | At any point where the ‘outermost projection height’ is greater than 7.5 metres || 14.501 – 15.000 | 1.425 | 1.900 || 14.001 – 14.500 | 1.350 | 1.800 || 13.501 – 14.000 | 1.275 | 1.700 || 13.001 – 13.500 | 1.200 | 1.600 || 12.501 – 13.000 | 1.125 | 1.500 || 12.001 – 12.500 | 1.050 | 1.400 || 11.501 – 12.000 | 0.975 | 1.300 || 11.001 – 11.500 | 0.900 | 1.200 || 10.501 – 11.000 | 0.825 | 1.100 || 10.500 or less | 0.750 | 1.000 || 2 metres plus 0.5 of a metre for every 3 metres or part of 3 metres by which the height exceeds 7.5 metres.$q$, 'VERIFIED_VERBATIM', $q$Medium density residential zone code p.P6-165 (PDF p.7); Major tourism zone code p.P6-174 (PDF p.4); Major tourism zone code p.P6-176 (PDF p.6); Schedule 10 p.SC10-13 to SC10-14 (PDF pp.13-14); Tables SC10.1.9/SC10.1.10 at SC10-21 (PDF p.21)$q$, NULL, $q$Medium density residential zone code / Major tourism zone code / Major tourism zone code + Schedule 10$q$, NULL, $q$https://www.livingstone.qld.gov.au/files/sharedassets/public/v/1/doing-business/documents/10_Sch10_Boundary_setbacks_for_zones_V4_Adopted_2025_02_18.pdf$q$, $q$SC1.2 Setback: "the shortest distance, measured horizontally, between the outermost projection of the building or structure to the vertical projection of the boundary of the lot where the building or structure is." Outermost projection excludes a retractable blind, fixed screen, rainwater fitting or ornamental attachment. Outermost projection height is measured to ground level directly below that point.$q$, $q$lsc_mdr_mt_side_rear_frontage_le15$q$);
SELECT define_rule($q${"rule_id": "LSC.lsc_mdr_mt_side_rear_frontage_le15", "instrument_version": "LSC_PLANNING_SCHEME_2018@2025-05-02", "topic": "SETBACK.SIDE", "title": "Medium density residential zone code Table 6.7.3.4.1 AO2.2; Major tourism zone code Table 6.8.1.4.1 AO2.1 (Capricorn International Resort Precinct); Major tourism zone code Table 6.8.1.4.1 AO4.2 (Grea", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "TABLE", "measurement": "SCHEME_SETBACK_SIDE", "operator": ">=", "value": {"op": "unencoded", "text": "OPH > 7.5 m: 2 + 0.5 * ceil((OPH - 7.5)/3)", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2025-05-02", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "LIVINGSTONE"}, {"level": "ZONE", "zone": "LSC:MEDIUM_DENSITY_RESIDENTIAL"}, {"level": "PRECINCT", "precinct": "LSC:MAJOR_TOURISM/CAPRICORN_INTERNATIONAL_RESORT"}, {"level": "PRECINCT", "precinct": "LSC:MAJOR_TOURISM/GREAT_KEPPEL_ISLAND"}], "subjects": ["ANY"], "sources": [{"key": "lsc_mdr_mt_side_rear_frontage_le15", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"unit\": \"m\", \"conditions\": [\"applies to side AND rear boundaries\", \"measured at any point by outermost projection height\", \"road frontage 14.501–15.000 m: OPH 2–4.5 m: 1.425 m; OPH 4.501–7.5 m: 1.900 m\", \"road frontage 14.001–14.500 m: OPH 2–4.5 m: 1.350 m; OPH 4.501–7.5 m: 1.800 m\", \"road frontage 13.501–14.000 m: OPH 2–4.5 m: 1.275 m; OPH 4.501–7.5 m: 1.700 m\", \"road frontage 13.001–13.500 m: OPH 2–4.5 m: 1.200 m; OPH 4.501–7.5 m: 1.600 m\", \"road frontage 12.501–13.000 m: OPH 2–4.5 m: 1.125 m; OPH 4.501–7.5 m: 1.500 m\", \"road frontage 12.001–12.500 m: OPH 2–4.5 m: 1.050 m; OPH 4.501–7.5 m: 1.400 m\", \"road frontage 11.501–12.000 m: OPH 2–4.5 m: 0.975 m; OPH 4.501–7.5 m: 1.300 m\", \"road frontage 11.001–11.500 m: OPH 2–4.5 m: 0.900 m; OPH 4.501–7.5 m: 1.200 m\", \"road frontage 10.501–11.000 m: OPH 2–4.5 m: 0.825 m; OPH 4.501–7.5 m: 1.100 m\", \"road frontage 10.500 m or less: OPH 2–4.5 m: 0.750 m; OPH 4.501–7.5 m: 1.000 m\", \"OPH > 7.5 m (any frontage <= 15 m): 2 m + 0.5 m for every 3 m or part of 3 m by which height exceeds 7.5 m\"], \"exceptions\": [\"Class 10a building or part may be within the setback - see Circumstance (C) rule\", \"rainwater tank (incl. stand) <= 2.4 m high (Circumstance (D)(a))\", \"ornamental/horticultural pergola or structure <= 2.4 m, unenclosed (Circumstance (D)(b))\", \"building or structure (or combination such as fence + retaining wall) not exceeding 2 m outermost projection height / combined height (Circumstance (F))\"], \"formula_text\": \"OPH > 7.5 m: 2 + 0.5 * ceil((OPH - 7.5)/3)\", \"parameter\": \"side and rear boundary setback by road frontage width and outermost projection height (OPH)\", \"operator\": \"conditional\", \"value\": null}\nLot conditions (not encoded): rectangular or near rectangular lot with road frontage <= 15 m\nStructure scope 'buildings or structures (a part of the building or structure)' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: YES - Part 1 s1.6(3): \"This planning scheme, through Part 5, regulates building work in accordance with sections 32 and 33 of the Building Act 1975.\" and s1.6(4)(c) lists \"Relevant zone codes\" (and (e) \"Seaspray Local Plan\") as building assessment provisions; the s1.6 editor's note cites \"alternative boundary clearances and site cover provisions for Class 1 and 10 structures under section 33\". Table 5.6.1 makes standalone Class 10a building work accepted subject to requirements against these AOs.\nResearcher notes: Table SC10.1.9 values transcribed from pdftotext -layout output of the official PDF (rows read left-to-right); the >7.5 m column is a single merged cell spanning all rows. Structures below 2 m OPH are effectively unregulated (table starts at 2 m and Circumstance (F) exempts them). Table SC10.1.3 has a second row for development with an outermost projection height exceeding 10 m (front: 6 m plus 0.3 m per metre over 10 m; side/rear: 3 m plus 0.3 m per metre over 10 m); not recorded as a separate rule because Class 10 structures of that height are not expected."}$q$::jsonb);
