SELECT define_provision($q$LSC_PLANNING_SCHEME_2018@2025-05-02$q$, $q$Rural residential zone code Table 6.5.5.4.1 AO3.1; Schedule 10 Table SC10.1.4 Side and Rear Boundaries$q$, 'ACCEPTABLE_OUTCOME', $q$AO3.1 Buildings or structures have a setback from from side, rear and road frontage lot boundaries in compliance with the setback standards identified in Table SC10.1.4 of Schedule 10. || Table SC10.1.4: Setback standards for development located in the Rural Residential Zone | The development is: (a) located within the Park Residential Precinct; or (b) not located within the Park Residential Precinct and it is on a lot having an area 0 m2 to 9,999 m2 | The side and rear setbacks identified in Circumstance (A) apply to buildings or structures unless the building or structure complies with Circumstance (B). | Circumstance (A): Buildings or structures have a setback from side and rear boundaries of at least five (5) metres. | Circumstance (B): A building or structure that: (a) if standalone, does not have an ‘outermost projection height’ exceeding two (2) metres; or (b) if involving a combination with other buildings or structures, does not result in a combined height exceeding two (2) metres. Editor’s note: An example of a ‘combination’ is a fence and a retaining wall or a building and a retaining wall.$q$, 'VERIFIED_VERBATIM', $q$Rural residential zone code p.P6-100 (PDF p.4); Schedule 10 p.SC10-17 (PDF p.17)$q$, NULL, $q$Rural residential zone code + Schedule 10$q$, NULL, $q$https://www.livingstone.qld.gov.au/files/sharedassets/public/v/1/doing-business/documents/10_Sch10_Boundary_setbacks_for_zones_V4_Adopted_2025_02_18.pdf$q$, $q$SC1.2 Setback: "the shortest distance, measured horizontally, between the outermost projection of the building or structure to the vertical projection of the boundary of the lot where the building or structure is." Outermost projection excludes a retractable blind, fixed screen, rainwater fitting or ornamental attachment. Outermost projection height is measured to ground level directly below that point.$q$, $q$lsc_rr_prp_or_lt1ha_side_rear$q$);
SELECT define_rule($q${"rule_id": "LSC.lsc_rr_prp_or_lt1ha_side_rear", "instrument_version": "LSC_PLANNING_SCHEME_2018@2025-05-02", "topic": "SETBACK.SIDE", "title": "Rural residential zone code Table 6.5.5.4.1 AO3.1; Schedule 10 Table SC10.1.4 Side and Rear Boundaries", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_SETBACK_SIDE", "operator": ">=", "value": 5, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2025-05-02", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "LIVINGSTONE"}, {"level": "PRECINCT", "precinct": "LSC:RURAL_RESIDENTIAL/PARK_RESIDENTIAL"}, {"level": "ZONE", "zone": "LSC:RURAL_RESIDENTIAL"}], "subjects": ["ANY"], "sources": [{"key": "lsc_rr_prp_or_lt1ha_side_rear", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"unit\": \"m\", \"conditions\": [\"applies to side AND rear boundaries\"], \"exceptions\": [\"building or structure (or combination e.g. fence + retaining wall) not exceeding 2 m outermost projection height / combined height\"], \"formula_text\": null, \"parameter\": \"side and rear boundary setback\", \"operator\": \">=\", \"value\": 5}\nLot conditions (not encoded): Park Residential Precinct (any lot size); or elsewhere in zone, lots 0 m2 to 9,999 m2\nStructure scope 'buildings or structures' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: YES - Part 1 s1.6(3): \"This planning scheme, through Part 5, regulates building work in accordance with sections 32 and 33 of the Building Act 1975.\" and s1.6(4)(c) lists \"Relevant zone codes\" (and (e) \"Seaspray Local Plan\") as building assessment provisions; the s1.6 editor's note cites \"alternative boundary clearances and site cover provisions for Class 1 and 10 structures under section 33\". Table 5.6.1 makes standalone Class 10a building work accepted subject to requirements against these AOs.\nResearcher notes: No Class 10a concession (unlike urban tables); applies equally to dwellings and outbuildings."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$LSC.lsc_rr_prp_or_lt1ha_side_rear@2025-05-02$q$;
