SELECT define_provision($q$LSC_PLANNING_SCHEME_2018@2025-05-02$q$, $q$Table 6.5.4.4.1 AO10.1 (Yaamba Historic Township Precinct)$q$, 'ACCEPTABLE_OUTCOME', $q$Where located in the Yaamba Historic Township Precinct | AO10.1 Buildings or structures have a setback from side, rear and road frontage lot boundaries in accordance with the following: (a) at any point where the ‘outermost projection height’ is between two (2) metres and 4.5 metres, a setback of at least twenty (20) metres; or (b) at any point where the ‘outermost projection height’ is greater than 4.5 metres, a setback of at least twenty (20) metres plus 0.3 of a metre for every additional metre or part thereof in height over 4.5 metres.$q$, 'VERIFIED_VERBATIM', $q$P6-90 (PDF p.9)$q$, NULL, $q$Rural zone code$q$, NULL, $q$https://www.livingstone.qld.gov.au/files/sharedassets/public/v/1/doing-business/documents/06_Pt6_654_Rural_Zone_Code_V4_Adopted_2025_02_18.pdf$q$, $q$SC1.2 Setback: "the shortest distance, measured horizontally, between the outermost projection of the building or structure to the vertical projection of the boundary of the lot where the building or structure is." Outermost projection excludes a retractable blind, fixed screen, rainwater fitting or ornamental attachment. Outermost projection height is measured to ground level directly below that point.$q$, $q$lsc_rur_yaamba_front$q$);
SELECT define_rule($q${"rule_id": "LSC.lsc_rur_yaamba_front", "instrument_version": "LSC_PLANNING_SCHEME_2018@2025-05-02", "topic": "SETBACK.FRONTAGE", "title": "Table 6.5.4.4.1 AO10.1 (Yaamba Historic Township Precinct)", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": 20, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2025-05-02", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "LIVINGSTONE"}, {"level": "PRECINCT", "precinct": "LSC:RURAL/YAAMBA_HISTORIC_TOWNSHIP"}], "subjects": ["ANY"], "sources": [{"key": "lsc_rur_yaamba_front", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"unit\": \"m\", \"conditions\": [\"outermost projection height 2 m to 4.5 m: 20 m\", \"outermost projection height > 4.5 m: 20 m plus 0.3 m per additional metre or part thereof over 4.5 m\"], \"exceptions\": [\"no requirement stated for parts below 2 m outermost projection height\"], \"formula_text\": \"20 + 0.3 * ceil(OPH - 4.5) for OPH > 4.5\", \"parameter\": \"road frontage setback\", \"operator\": \">=\", \"value\": 20}\nStructure scope 'buildings or structures' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: YES - Part 1 s1.6(3): \"This planning scheme, through Part 5, regulates building work in accordance with sections 32 and 33 of the Building Act 1975.\" and s1.6(4)(c) lists \"Relevant zone codes\" (and (e) \"Seaspray Local Plan\") as building assessment provisions; the s1.6 editor's note cites \"alternative boundary clearances and site cover provisions for Class 1 and 10 structures under section 33\". Table 5.6.1 makes standalone Class 10a building work accepted subject to requirements against these AOs.\nResearcher notes: Table 5.6.1 applies AO6.1, AO8.1, AO9.1, AO9.2 and AO10.1 to standalone Class 10a building work in the Yaamba Historic Township Precinct. Dwelling houses here are code assessable (Table 5.4.4.4). The ZONE-level raw scope for \"Rural Zone\" also covers this precinct; curator should make the precinct rule override the zone-wide Schedule 10 rules."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$LSC.lsc_rur_yaamba_front@2025-05-02$q$;
INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$LSC.lsc_rur_yaamba_front@2025-05-02$q$, $q$QDC12.A1a.ROAD_SETBACK$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
