SELECT define_provision($q$LSC_PLANNING_SCHEME_2018@2025-05-02$q$, $q$Table 7.2.4.1 AO5.1(a), (c)$q$, 'ACCEPTABLE_OUTCOME', $q$AO5.1 Buildings or structures (other than fences) have a setback from road frontage lot boundaries in accordance with the following: (a) where located on a lot which has an approved building location envelope, the development is within the boundaries of the approved building location envelope; or (b) where located in the Seaspray Residential Low Density Precinct or the Seaspray Residential Medium Density Precinct and the lot does not have an approved building location envelope: (i) a setback from the primary road frontage lot boundary of at least six (6) metres; and (ii) a setback from a secondary road frontage lot boundary of at least three (3) metres; or (c) where located in the Seaspray Community and Recreation Precinct and the lot does not have an approved building location envelope: (i) a setback from any road frontage lot boundary of at least six (6) metres.$q$, 'VERIFIED_VERBATIM', $q$Table 7.2.4.1, P7-6 to P7-8 (PDF pp.6-8)$q$, NULL, $q$Seaspray local plan code$q$, NULL, $q$https://www.livingstone.qld.gov.au/files/sharedassets/public/v/1/doing-business/documents/07_pt7_local_plan_codes_v4_adopted_2025_02_18.pdf$q$, $q$SC1.2 Setback: "the shortest distance, measured horizontally, between the outermost projection of the building or structure to the vertical projection of the boundary of the lot where the building or structure is." Outermost projection excludes a retractable blind, fixed screen, rainwater fitting or ornamental attachment. Outermost projection height is measured to ground level directly below that point.$q$, $q$lsc_seaspray_comrec_front$q$);
SELECT define_rule($q${"rule_id": "LSC.lsc_seaspray_comrec_front", "instrument_version": "LSC_PLANNING_SCHEME_2018@2025-05-02", "topic": "SETBACK.FRONTAGE", "title": "Table 7.2.4.1 AO5.1(a), (c)", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": 6, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2025-05-02", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "LIVINGSTONE"}], "subjects": ["ANY"], "sources": [{"key": "lsc_seaspray_comrec_front", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"unit\": \"m\", \"conditions\": [\"Seaspray Community and Recreation Precinct\", \"no approved building location envelope\"], \"exceptions\": [\"fences\", \"lot with an approved building location envelope\"], \"formula_text\": null, \"parameter\": \"setback from any road frontage lot boundary\", \"operator\": \">=\", \"value\": 6}\nLot conditions (not encoded): lot without an approved building location envelope\nLocal plan: Seaspray Local Plan\nStructure scope 'Buildings or structures (other than fences)' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: YES - Part 1 s1.6(3): \"This planning scheme, through Part 5, regulates building work in accordance with sections 32 and 33 of the Building Act 1975.\" and s1.6(4)(c) lists \"Relevant zone codes\" (and (e) \"Seaspray Local Plan\") as building assessment provisions; the s1.6 editor's note cites \"alternative boundary clearances and site cover provisions for Class 1 and 10 structures under section 33\". Table 5.6.1 makes standalone Class 10a building work accepted subject to requirements against these AOs.\nResearcher notes: Seaspray local plan code prevails over zone codes (s1.5(d)). Table 5.8.1.5 makes standalone Class 10a building work in all Seaspray precincts accepted subject to requirements against AO5.1 and AO5.2 (among others). Where the lot has an approved building location envelope (BLE), the BLE governs instead (plans held by Council). Fences are excluded. Underlying zone of the Seaspray area not confirmed; scoped by local plan precinct. Dwelling houses are not identified as accepted/code in this precinct (Table 5.8.1 MCU tables list dwelling house for the residential precincts); included for completeness."}$q$::jsonb);
