INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$LIVINGSTONE$q$, $q$LSC_PLANNING_SCHEME_2018$q$, 'MEDIUM', $q$Underlying zone(s) of the Seaspray Local Plan area were not confirmed (mapping not checked); Seaspray rules are scoped by local plan precinct only. Confirm whether the zone-code Schedule 10 setbacks also apply there (Table 5.6.1 vs Table 5.8.1.5).$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$LIVINGSTONE$q$, $q$LSC_PLANNING_SCHEME_2018$q$, 'MEDIUM', $q$Emerging Community Zone: Schedule 10 does not apply in approved structure plan areas / preliminary approvals (which may set their own setbacks or building envelopes); these are not captured.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$LIVINGSTONE$q$, $q$LSC_PLANNING_SCHEME_2018$q$, 'MEDIUM', $q$Swimming pools are not named in Schedule 10; whether an in-ground pool is a 'building or structure' with an outermost projection height over 2 m (and so subject to the 6 m front setback) needs curator interpretation.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$LIVINGSTONE$q$, $q$LSC_PLANNING_SCHEME_2018$q$, 'MEDIUM', $q$Raw scope "Rural Zone" (ZONE level) also covers the Yaamba Historic Township Precinct, where AO10.1 applies instead of Schedule 10; consumer must give the precinct rule precedence.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$LIVINGSTONE$q$, $q$LSC_PLANNING_SCHEME_2018$q$, 'MEDIUM', $q$Medium density / Major tourism Table SC10.1.3 second row (outermost projection height > 10 m) not recorded as separate rules.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$LIVINGSTONE$q$, $q$LSC_PLANNING_SCHEME_2018$q$, 'MEDIUM', $q$Figures SC10.1.5-SC10.1.8 (corner truncation, secondary frontage, open carport, rural example) are images only and were not transcribed.$q$);
